using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;
using Cascade.Domain;using Cascade.Application;using Cascade.Content;using Cascade.Persistence;using Cascade.Solver;using Newtonsoft.Json;
class ReleaseProbe {
 static string root,folder; static ContentCatalog catalog;
 static void Require(bool x,string message){if(!x)throw new Exception(message);}
 static void Write(string name,object value)=>File.WriteAllText(Path.Combine(folder,name),JsonConvert.SerializeObject(value,Formatting.Indented));
 static void Main(string[] args){root=args[0];folder=args[1];string Read(string name)=>File.ReadAllText(Path.Combine(root,"Data",name));
  catalog=ContentImporter.Import(Read("levels.json"),Read("localized_levels.json"),Read("words_en.json"),Read("words_ru.json"),Read("words_uk.json"),Read("campaign_extension.json"));
  Write("journey-order.json",JourneyStory.NodeIds.ToArray());
  Write("catalog-observation.json",new { CatalogHash=catalog.ContentHash,SourceHashes=catalog.PrimaryLevels.Concat(catalog.LocalizedLevels).Select(c=>c.Definition.ContentHash).Distinct().ToArray()});
  if(args.Contains("--manifest"))return; if(args.Contains("--proof-scaling")){ProofScaling();return;} if(args.Contains("--publish"))throw new ArgumentException("Use Tools/publish_campaign_recipes.py to publish verified resources."); if(args.Contains("--missions")){Missions();return;} Profiles(); Forgery(); Fuzz(); if(!args.Contains("--profile-only"))Triads(); Console.WriteLine("Independent probes complete.");
 }
 static void Publish(){var rows=new Dictionary<string,DescentStage[]>();foreach(var c in catalog.PrimaryLevels){var run=DescentRun.Build(c.Definition,version:6);Require(run!=null,"Missing published recipe");run.Validate(c.Definition,c.Locale);rows.Add(c.Definition.CampaignNodeId,run.Stages);if(rows.Count%100==0)Console.WriteLine("Published recipes: "+rows.Count);}File.WriteAllText(Path.Combine(root,"Data","production_triad_recipes.json"),JsonConvert.SerializeObject(rows));}
 static void Profiles(){var measurements=new List<object>();var nodes=catalog.PrimaryLevels.Select(c=>c.Definition.CampaignNodeId).ToArray();
  foreach(int count in new[]{0,60,180,540})foreach(int grants in new[]{0,1000,5000,10000}){
   var profile=new PlayerProfile();foreach(string mode in new[]{"Shapes","Words","Mixed"}){profile.SelectJourney(mode);foreach(var n in nodes.Take(count))profile.Clears.Add(new ClearReceipt{CampaignNodeId=n,AttemptId=Guid.NewGuid().ToString("D"),ContentHash=new string('a',64),BestStars=3,BestScore=1680});}
   profile.Rewards.Synchronize(nodes.Take(count));for(int i=0;i<grants;i++)profile.Monetization.Grants.Add(new GrantReceipt{Id="admob_"+Guid.NewGuid().ToString("D"),Kind="coins",Amount=40});profile.Monetization.BonusCoins=grants*40;
   string directory=Path.Combine(Path.GetTempPath(),"CascadeAuditProfile",Guid.NewGuid().ToString("N"));var store=new ProfileStore(Path.Combine(directory,"profile.json"));var ms=new List<double>();
   try{for(int pass=0;pass<5;pass++){var timer=Stopwatch.StartNew();store.Save(profile);ms.Add(timer.Elapsed.TotalMilliseconds);Require(store.Load().Recovery==SaveRecovery.None,"Profile roundtrip");}
    var queueMs=new List<double>();for(int pass=0;pass<5;pass++){var timer=Stopwatch.StartNew();store.QueueSave(profile);queueMs.Add(timer.Elapsed.TotalMilliseconds);store.Flush();Require(store.Load().Recovery==SaveRecovery.None,"Queued roundtrip");}
    int cloudBytes=System.Text.Encoding.UTF8.GetByteCount(CloudJson.Encode(profile));
    measurements.Add(new{clearsPerMode=count,modes=3,grants,bytes=new FileInfo(store.Path).Length,cloudProfileBytes=cloudBytes,packedCloudBytes=System.Text.Encoding.UTF8.GetByteCount(CloudProfilePayload.Pack(CloudJson.Encode(profile))),stableSyncRequestBytes=System.Text.Encoding.UTF8.GetByteCount(CloudProfilePayload.Pack(CloudJson.Encode(profile)))+150,stableSyncFits=System.Text.Encoding.UTF8.GetByteCount(CloudProfilePayload.Pack(CloudJson.Encode(profile)))+150<=CloudProfilePayload.MaxWireBytes,saveMedianMs=ms.OrderBy(x=>x).ElementAt(2),saveMaxMs=ms.Max(),captureMedianMs=queueMs.OrderBy(x=>x).ElementAt(2),captureMaxMs=queueMs.Max(),wallet=profile.Rewards.EarnedCoins(nodes)+profile.Monetization.BonusCoins});
   }finally{if(Directory.Exists(directory))Directory.Delete(directory,true);}
  }
  var overflow=new MonetizationLedger();for(int i=0;i<10001;i++)overflow.Grants.Add(new GrantReceipt{Id="grant_"+i,Kind="coins",Amount=40});bool rejected=false;try{overflow.Validate();}catch{rejected=true;}Require(rejected,"Expected documented ledger ceiling");
  Write("profile-scaling.json",measurements);Write("economy-totals.json",new{nodes=nodes.Length,earnedCoins=nodes.Length*40+(nodes.Length/10)*100,trophies=ShopCatalog.TrophyIds.Length,totalCatalogPrice=ShopCatalog.TrophyIds.Sum(ShopCatalog.TrophyPrice),tools=Enum.GetValues(typeof(TravelTool)).Cast<TravelTool>().Select(t=>new{tool=t.ToString(),price=ShopCatalog.Price(t)}),ledgerMaxGrants=10000,overflowRejected=rejected});
 }
 static void ProofScaling(){
  var recipes=JsonConvert.DeserializeObject<Dictionary<string,DescentStage[]>>(File.ReadAllText(Path.Combine(root,"Data","production_triad_recipes.json")));var profile=new PlayerProfile();int replays=0;
  var timer=Stopwatch.StartNew();
  foreach(var source in catalog.PrimaryLevels.Concat(catalog.LocalizedLevels)){
   var run=new DescentRun{Version=6,SourceHash=source.Definition.ContentHash,Stages=recipes[source.Definition.CampaignNodeId]};AttemptService final=null;
   for(int stage=0;stage<3;stage++){final=new AttemptService(run.Level(source.Definition,stage),source.Locale);foreach(string command in run.Stages[stage].Witness)final.Execute(command=="D"?PuzzleCommand.Drop:command.StartsWith("R")?PuzzleCommand.Reach(int.Parse(command.Substring(1).Split(':')[0]),int.Parse(command.Split(':')[1])):PuzzleCommand.Swap(int.Parse(command)));Require(final.Current.Status==PuzzleStatus.Won,"Published witness failed");if(stage<2)run.AcceptCheckpoint(source.Definition,final);replays++;}
   profile.SelectJourney(final.Mode.ToString());profile.Descent=run;profile.RecordClear(final,LevelCompletion.From(final,null,run.Performance(final)));
  }
  profile.Descent=null;profile.Rewards.Synchronize(profile.AllClears.Select(c=>c.CampaignNodeId));for(int i=0;i<10000;i++)profile.Monetization.Grants.Add(new GrantReceipt{Id="admob_"+Guid.NewGuid().ToString("D"),Kind="coins",Amount=40});profile.Monetization.BonusCoins=400000;profile.Validate();
  File.WriteAllText(Path.Combine(folder,"proof-profile.json"),CloudJson.Encode(profile));
  string raw=CloudJson.Encode(profile),packed=CloudProfilePayload.Pack(raw);Require(CloudProfilePayload.Unpack(packed)==raw,"Proof transport roundtrip");
  Write("proof-profile-scaling.json",new{verifiedReplays=replays,actualModeClears=profile.AllClears.Count(),rawBytes=System.Text.Encoding.UTF8.GetByteCount(raw),packedBytes=System.Text.Encoding.UTF8.GetByteCount(packed),fitsRequest=System.Text.Encoding.UTF8.GetByteCount(packed)+150<CloudProfilePayload.MaxWireBytes,elapsedMs=timer.Elapsed.TotalMilliseconds});
 }
 static void Forgery(){var nodes=catalog.PrimaryLevels.Select(c=>c.Definition.CampaignNodeId).ToArray();var forged=new PlayerProfile();foreach(var n in nodes)forged.Clears.Add(new ClearReceipt{CampaignNodeId=n,AttemptId=Guid.NewGuid().ToString("D"),ContentHash=new string('a',64),BestStars=5,BestScore=2100});forged.Rewards.Synchronize(nodes);forged.Validate();var result=CloudReconciler.ImportLocal(forged,nodes);Write("forged-progress.json",new{claimedClears=540,acceptedClears=result.Profile.Clears.Count,coins=result.Profile.Rewards.EarnedCoins(nodes),conflict=result.EconomyConflict,proof="Actual local migration merge accepts fabricated allowed-node receipts; no gameplay replay or source hash lookup at this boundary. Not a live service attack."});}
 static void Fuzz(){int steps=0,traces=0;var random=new Random(91357);
  foreach(var content in catalog.PrimaryLevels.Take(40))for(int trial=0;trial<100;trial++){
   var level=content.Definition;var resolver=new PuzzleResolver(level);var state=resolver.CreateInitialState();var expected=level.TargetSymbolIds.OrderBy(s=>s.PersistedId).ToArray();
   for(int move=0;move<60&&state.Status==PuzzleStatus.Playing;move++){
    var options=Enumerable.Range(0,level.InitialSymbolIds.Count-1).Select(PuzzleCommand.Swap).Append(PuzzleCommand.Drop).ToArray();var result=resolver.Resolve(state,options[random.Next(options.Length)]);
    Require(result.State.Row.OrderBy(s=>s.PersistedId).SequenceEqual(expected),"Multiset changed "+level.PuzzleId);state=result.State;steps++;
   }traces++;
  }Write("random-traces.json",new{seed=91357,traces,transitions=steps,verified="No exceptions; persistent row multiset after accepted and rejected commands; terminal status ends trace. Canonical first40; not a proof of all rule combinations."});
 }
 static void Missions(){var rows=new List<object>();int offers=0,replays=0;foreach(var content in catalog.PrimaryLevels){using var stop=new CancellationTokenSource(TimeSpan.FromSeconds(45));var source=content.Definition;var baseline=DescentRun.Build(source,version:6,cancellation:stop.Token);var timer=Stopwatch.StartNew();var run=CampaignTriads.BuildPersonalMission(source,17,null,stop.Token,reference:baseline);if(run!=null){offers++;run.Validate(source,content.Locale);replays+=3;int extra=run.Stages.Sum(s=>s.Minimum)-baseline.Stages.Sum(s=>s.Minimum);Require(extra>=1&&extra<=Math.Max(4,baseline.Stages.Sum(s=>s.Minimum)/3),"Mission difficulty band");foreach(var binding in catalog.LocalizedLevels.Where(c=>c.Definition.CampaignNodeId==source.CampaignNodeId)){new DescentRun{Version=6,SourceHash=binding.Definition.ContentHash,Stages=run.Stages}.Validate(binding.Definition,binding.Locale);replays+=3;}rows.Add(new{node=source.CampaignNodeId,offered=true,extra,ms=timer.Elapsed.TotalMilliseconds});}else rows.Add(new{node=source.CampaignNodeId,offered=false,ms=timer.Elapsed.TotalMilliseconds});File.WriteAllText(Path.Combine(folder,"missions.json"),JsonConvert.SerializeObject(rows,Formatting.Indented));}Write("missions-summary.json",new{sources=catalog.PrimaryLevels.Count,serial=17,offers,notOffered=catalog.PrimaryLevels.Count-offers,primaryLocalizedReplays=replays,note="One reproducible serial across whole catalog; not all serials or live scheduling/UI."});Console.WriteLine("Mission offers: "+offers);}
 static void Triads(){var rows=new List<object>();var signatures=new Dictionary<string,List<string>>();int replays=0,bombs=0,unsafeQueries=0,benefitQueries=0;var total=Stopwatch.StartNew();
  foreach(var content in catalog.PrimaryLevels){var source=content.Definition;using var stop=new CancellationTokenSource(TimeSpan.FromSeconds(45));var timer=Stopwatch.StartNew();var run=DescentRun.Build(source,version:6,cancellation:stop.Token);double planMs=timer.Elapsed.TotalMilliseconds;Require(run!=null,"No recipe "+source.CampaignNodeId);run.Validate(source,content.Locale);replays+=3;
   foreach(var binding in catalog.LocalizedLevels.Where(c=>c.Definition.CampaignNodeId==source.CampaignNodeId)){new DescentRun{Version=6,SourceHash=binding.Definition.ContentHash,Stages=run.Stages}.Validate(binding.Definition,binding.Locale);replays+=3;}
   string normalized=string.Join(";",source.TargetSymbolIds.Select(s=>source.TargetSymbolIds.ToList().IndexOf(s)))+"|"+string.Join("|",run.Stages.Select(s=>s.Triad.Fingerprint));if(!signatures.ContainsKey(normalized))signatures[normalized]=new List<string>();signatures[normalized].Add(source.CampaignNodeId);
   for(int stage=0;stage<3;stage++){var level=run.Level(source,stage);Require(CampaignTriads.HasLiveBombWindows(level),"Inert bomb "+source.CampaignNodeId);if(level.Floors.Any(f=>f.Bomb!=null)){bombs+=level.Floors.Count(f=>f.Bomb!=null);unsafeQueries++;Require(CampaignTriads.WithMissedBomb(level,stop.Token).Status==SearchStatus.Unsolvable,"Bomb bypass "+source.CampaignNodeId);}
    benefitQueries++;Require(CampaignTriads.BenefitsRequired(level,stop.Token),"Benefit bypass "+source.CampaignNodeId);
    rows.Add(new{node=source.CampaignNodeId,lessonNumber=source.CampaignLessonNumber,stage=stage+1,lesson=((MechanicLesson)run.Stages[stage].Triad.Lesson).ToString(),width=level.TargetSymbolIds.Count,floors=level.Floors.Count,minimum=run.Stages[stage].Minimum,planMs,hp=level.Floors.Sum(f=>f.BaseDurability),bombs=level.Floors.Count(f=>f.Bomb!=null),repairs=level.Floors.Count(f=>f.Repair!=null),keys=level.Floors.Count(f=>f.Key!=null),powers=level.Floors.Count(f=>f.Powerup!=null),wind=level.Floors.Count(f=>f.GustAfterSwaps>0),entry=level.Floors.Count(f=>f.EntryTransform!=EntryTransform.None),linked=level.Floors.Count(f=>f.LinkedPair.HasValue),fragile=level.Floors.Count(f=>f.FragileEdges.Count>0),stamps=level.Floors.Count(f=>f.OptionalStamp!=null)});
   }if(signatures.Sum(p=>p.Value.Count)%100==0)Console.WriteLine("Triads: "+signatures.Sum(p=>p.Value.Count));
  }
  Write("triads.json",rows);Write("structural-repeat-groups.json",signatures.Values.Where(v=>v.Count>1).OrderByDescending(v=>v.Count).ToArray());Write("triad-summary.json",new{campaign=catalog.PrimaryLevels.Count,stages=rows.Count,primaryLocalizedReplays=replays,bombs,unsafeQueries,benefitQueries,normalizedUniqueTriads=signatures.Count,elapsedSeconds=total.Elapsed.TotalSeconds,note="Same target equality pattern and exact recipe fields; structural fingerprint, not exhaustive graph isomorphism. Duration from Mono on this Mac during concurrent tests, not iPhone timing."});
 }
}
